-- This script upserts deterministic records and does not delete manual rows.

begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "0a92fb7d-f562-5752-94af-3f71903e88ea", "feature_slug": "authentication-and-signup", "title": "3. Configuration Reference", "content": "### Authentication Methods\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| `auth_methods` | Which identity providers members must use | `[\"line\", \"tel\"]` | Merchant-specific |\n\nRetrieved by frontend via `bff_get_auth_config(merchant_code)`.\n\n### OTP Settings\n\n| Setting | Value |\n|---|---|\n| Code length | 6 digits |\n| Expiry | 10 minutes |\n| Max attempts | 3 per session |\n| SMS provider | 8x8 |\n| Resend cooldown | 30 seconds (frontend) |\n\n### Token Configuration\n\n| Token | Expiry | Storage |\n|---|---|---|\n| Member access token | 24 hours | `loyalty_access_token` cookie (JS-readable) |\n| Member refresh token | 30 days | `loyalty_refresh_token` cookie (httpOnly) |\n| Admin access token | ~1 hour (Supabase default) | Supabase client (automatic) |\n\n### Profile Form Template\n\n| Setting | What it controls | Source |\n|---|---|---|\n| Default fields | Standard user fields (name, email, etc.) | `user_field_config` |\n| Custom fields | Merchant-defined fields | `form_templates` + `form_fields` (template code `USER_PROFILE`) |\n| Persona selection | Persona groups and avatars | `persona_groups` + `personas` |\n| PDPA consents | Privacy notices and consent checkboxes | `consent_versions` |\n| Field visibility by persona | Which fields appear per persona | `persona_ids` array on each field |\n\nTemplate cached in Redis for 5 minutes (`merchant:{id}:user_profile_template:all_languages`). Persona filtering applied per-request based on the caller''s JWT.", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/authentication-and-signup.md#L41 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f8595d579358e98c8b61173de49e3ca5b70e57cc71403ec61313e73e5557382e", "truncated": false}, "is_active": true}, {"id": "d9e3599a-ceab-5cad-b83b-986f6621cedb", "feature_slug": "authentication-and-signup", "title": "Security Model", "content": "### Row Level Security (RLS)\n\n**All user data filtered by merchant context:**\n\n```sql\n-- RLS Policy Example\nCREATE POLICY \"Users see own merchant data\"\nON user_accounts\nFOR ALL\nUSING (\n  merchant_id = get_current_merchant_id()\n);\n```\n\n**merchant_id extracted from:**\n1. JWT claim: `merchant_id`\n2. Or custom header: `x-merchant-id`\n\n**Function:** `get_current_merchant_id()` reads from auth context\n\n---\n\n### Token Expiry\n\n| Token Type | Expiry |\n|------------|--------|\n| End-user access token | 24 hours |\n| End-user refresh token | 30 days |\n| Admin access token | Supabase default (~1 hour) |\n\n**Refresh Flow:**\n```\nAccess token expires (24 hours)\n        ↓\nClient sends refresh_token\n        ↓\nEdge Function validates refresh token\n        ↓\nIssues new access_token (24 hours)\n        ↓\nClient stores new token\n```\n\n---", "content_format": "markdown", "knowledge_type": "implementation_constraints", "perspectives": ["implementation", "technical", "testing"], "output_uses": ["implementation_brief", "qa_testing", "technical_docs"], "scope": "be", "source_ref": "requirements/Authentication.md#L394 Security Model", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "constraints", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "d9c11ffb3f651d7ccf13333ee5215186a7142f3d842e4be6ceaa6832d7ff83cc", "truncated": false}, "is_active": true}, {"id": "7fc0564d-818f-558a-b456-629761ae5e86", "feature_slug": "authentication-and-signup", "title": "Security Considerations", "content": "### JWT Secret Must Match\n\n**All services validating JWTs must use the SAME secret:**\n\n| Service | Uses Secret For | Environment Variable |\n|---------|----------------|---------------------|\n| bff-auth-complete | Signing JWTs | `SUPABASE_JWT_SECRET` (auto) |\n| Supabase RPC/PostgREST | Validating JWTs | Project secret (built-in) |\n| crm-api | Validating JWTs | `JWT_SECRET` (manual) |\n| crm-event-processors | Validating JWTs | `SUPABASE_SERVICE_ROLE_KEY` (RPC calls) |\n\n**If any mismatch:**\n- Signature validation fails\n- \"Invalid token\" or \"PGRST301\" errors\n- API calls fail\n\n---\n\n### Key Rotation Impact\n\n**When you rotate Supabase''s JWT secret:**\n\n**What happens:**\n1. New secret becomes active\n2. Old secret moves to \"Previously used keys\"\n3. **Both secrets remain valid** (grace period)\n4. Existing tokens continue to work (Supabase validates with old secret)\n5. New tokens signed with new secret\n\n**What you must do:**\n1. Update `JWT_SECRET` in ALL external services (crm-api, etc.)\n2. Wait for grace period to end (all old tokens expire)\n3. Or force users to login again (invalidates old tokens)\n\n**DON''T:**\n- ❌ Set custom JWT_SECRET in Edge Functions (breaks Supabase validation)\n- ❌ Rotate without updating external services\n- ❌ Use different secrets for signing vs validation\n\n---", "content_format": "markdown", "knowledge_type": "implementation_constraints", "perspectives": ["implementation", "technical", "testing"], "output_uses": ["implementation_brief", "qa_testing", "technical_docs"], "scope": "be", "source_ref": "requirements/Authentication.md#L781 Security Considerations", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "constraints", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "516a255cef33f93083d9c24bb8d43fc89c51fb6a575ca47b47779cc07e074f07", "truncated": false}, "is_active": true}, {"id": "ed484181-5dfd-58a4-91fa-1032bdb8a378", "feature_slug": "authentication-and-signup", "title": "2. Key Concepts", "content": "**Authentication Methods** — Merchant-configurable combination of identity providers. Three configurations: `[\"line\"]` (LINE only), `[\"tel\"]` (phone OTP only), `[\"line\", \"tel\"]` (both required). Stored in `merchant_master.auth_methods`. Example: A Thai-market merchant sets `[\"line\", \"tel\"]` so members must verify both LINE and phone.\n\n**Custom JWT** — The member access token, signed with Supabase''s project secret using HS256. Contains claims: `sub`, `merchant_id`, `user_id`, `phone`, `line_id`, `role`, `aud`, `iss`, `exp`. Supabase PostgREST validates this token identically to native Supabase Auth JWTs. Admin JWTs are standard Supabase Auth tokens with no custom claims.\n\n**`next_step`** — API-driven state returned by `bff-auth-complete`. Five possible values:\n\n| Value | Meaning | JWT issued? |\n|---|---|---|\n| `verify_line` | Member needs to connect LINE | Sometimes |\n| `verify_tel` | Member needs to verify phone | Sometimes |\n| `complete_profile_new` | New member, show full registration form | Yes |\n| `complete_profile_existing` | Returning member, show missing fields | Yes |\n| `complete` | All done, go to homepage | Yes |\n\n**`form_step`** — Frontend-only state tracking which section of the multi-step profile form the member is viewing. Sequence: `persona` → `default_field` → `custom_field` → `pdpa`. Steps with no content are automatically skipped.\n\n**`bff-auth-complete`** — The central hub edge function. Handles all auth scenarios: finds or creates users, validates OTP, links auth methods, generates JWTs, evaluates profile completion, and returns the `next_step` + `missing_data` payload. Every auth flow routes through this single function.\n\n**Phone Normalization** — All phone numbers are converted to international format before storage or lookup. `0966564526` → `+66966564526`. `+660966564526` → `+66966564526` (removes extra 0). Applied in both `auth-send-otp` and `bff-auth-complete`.\n\n**`is_signup_form_complete`** — Boolean flag on `user_accounts`. Set to `true` when the member submits the profile form via `bff_save_user_profile`. Controls whether `missing_data` contains the full form or only newly-added required fields.\n\n**Auth Drawer** — Bottom-sheet popup (vaul drawer) in the member app that handles the entire auth + profile completion flow. Always mounted, opens via AuthProvider state machine. Renders auth screens or profile form steps depending on `next_step`.\n\n**Token Expiry** — Access token: 24 hours (member), ~1 hour (admin). Refresh token: 30 days (member). Tokens stored in cookies: `loyalty_access_token` (readable by JS) and `loyalty_refresh_token` (httpOnly).\n\n**Deactivated Default Fields** — `phone` and `line_id` fields exist in `user_field_config` but are set to `active_status = false`. These are managed by the auth flow, not shown in the signup form.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/authentication-and-signup.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "13b104fcd234801698749c303c697e86519f00309949bc5c0bba4f0ce3b2fe42", "truncated": false}, "is_active": true}, {"id": "04c87105-b0c1-5a43-a69e-a3bbb2b5d216", "feature_slug": "authentication-and-signup", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch:** \"Members sign in using LINE and/or phone OTP depending on your merchant settings. The system guides them through identity verification and profile completion automatically.\"\n\n**Top support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Member can''t log in\" | Check `auth_methods` config — does the member have the required methods linked? Check `user_accounts` for `tel`/`line_id` values |\n| \"OTP not received\" | SMS delivery issue (8x8 provider). Verify phone format is correct. OTP expires in 10 minutes, max 3 attempts per session |\n| \"Member stuck on profile form\" | Check `is_signup_form_complete` flag. If `false`, they haven''t submitted the form. If `true` but still prompted, new required fields were added |\n| \"Member sees ''Could not load registration form''\" | Edge function failed to fetch profile template. Member should tap Retry button. If persistent, check `bff_get_user_profile_template` function |\n| \"Member linked wrong LINE account\" | `line_id` is stored on `user_accounts`. Requires manual update — no self-service LINE unlink in the current system |\n| \"Error: ''Credentials belong to different accounts''\" | Member''s LINE and phone are registered to separate `user_accounts` records. Requires manual account merge |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/authentication-and-signup.md#L178 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8b92c2c79dcfd38a243fbde49e00a70798d93cca1aa01f75ff72056cb6882d20", "truncated": false}, "is_active": true}, {"id": "6890268c-7562-56a7-8060-a6f00f8fc4b2", "feature_slug": "authentication-and-signup", "title": "1. Overview", "content": "Authentication and signup form a single flow from the member''s perspective: open the app, prove your identity, fill in your profile, and land on the homepage. The system uses a dual architecture — members authenticate through LINE OAuth and/or Phone OTP via custom JWTs, while admins use standard Supabase Auth (email + password). This guide covers both, with emphasis on the member-facing flow since it contains the complex logic.\n\nThe entire member flow is orchestrated by a single value: `next_step`. Returned by the central edge function `bff-auth-complete`, this value tells the frontend exactly which screen to show next — whether that''s a LINE login prompt, a phone verification form, a profile registration form, or a direct redirect to the homepage. Every authentication scenario, from brand-new users to returning members who need to link a new auth method, resolves through the same `next_step` state machine.\n\nFor merchants, the system solves two problems: (1) flexible identity — each merchant chooses which auth methods their members use (LINE only, phone only, or both), and (2) progressive profile completion — the signup form adapts based on what data the member is still missing, even if new required fields are added after initial registration.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/authentication-and-signup.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "528864f17e72f929f79839f418dfa14aec9439230d997169ef8f23162c19181f", "truncated": false}, "is_active": true}, {"id": "1e0977eb-ae77-55b3-bb8c-b3ac49dc14e6", "feature_slug": "authentication-and-signup", "title": "8. Related Features", "content": "| Feature | Connection to Authentication & Signup |\n|---|---|\n| Forms | Profile completion uses the Forms system (`form_templates`, `form_fields`) for custom merchant-defined fields. See `Forms.md`. |\n| Tags & Persona | Persona selection during signup determines which profile fields are visible. Persona-scoped fields only appear for matching personas. See `Tag_and_Persona.md`. |\n| Currency | `get_user_summary()` is merged into the auth response when `next_step=complete`, providing points balance on first load. See `Currency.md`. |\n| Translation | Profile form template supports multi-language via `p_language` parameter. See `Translation_System.md`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/authentication-and-signup.md#L283 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "7a839fe2ff1b84b1e5e468259c3f98735ace61cb4b176d65514c49328c145f69", "truncated": false}, "is_active": true}, {"id": "45c0aa5e-5056-5d94-87ac-75d490167c67", "feature_slug": "authentication-and-signup", "title": "Authentication Flow Comparison", "content": "### End-User (Custom)\n\n```\n1. User opens app\n2. Call bff_get_auth_config(merchant_code)\n3. Show LINE button and/or Phone input based on config\n4. User authenticates (LINE OAuth, Phone OTP, or both)\n5. Call bff-auth-complete with credentials\n6. Receive custom JWT + refresh token\n7. Store tokens in localStorage\n8. Use access_token for all API calls\n```\n\n**Token Usage:**\n```javascript\n// All API calls\nheaders: {\n  ''Authorization'': `Bearer ${access_token}`\n}\n```\n\n---\n\n### Admin (Supabase Auth)\n\n```\n1. Admin enters email + password\n2. Call supabase.auth.signInWithPassword()\n3. Receive Supabase Auth JWT\n4. Store in Supabase client (automatic)\n5. Use for admin dashboard calls\n```\n\n**Token Usage:**\n```javascript\n// Automatic - Supabase client handles it\nconst { data } = await supabase.from(''table'').select();\n```\n\n---", "content_format": "markdown", "knowledge_type": "technical_flow", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "integration", "source_ref": "requirements/Authentication.md#L441 Authentication Flow Comparison", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "flow", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "628efbdb831b0a4114848cff3ba90778decf7c403d3906caef1cef0fc0b986d2", "truncated": false}, "is_active": true}, {"id": "6cd86c03-80a6-5e85-82de-7da382f908d1", "feature_slug": "authentication-and-signup", "title": "Authentication Domain Reference", "content": "**Keywords:** auth, JWT, token, login, LINE, OTP, phone, access token, refresh token, custom JWT, merchant auth, secret, PGRST301\n**Source:** `Authentication.md`\n|---|---|---|\n| Function | Parameters | Returns | Lines |\n|---|---|---|---|\n| `bff_get_auth_config(p_merchant_code)` | `p_merchant_code (text)` | `{ auth_methods: [\"line\",\"tel\"] }` | (Signup_Login.md 25–41) |\n| `auth-line` (Edge Function) | `{ code, merchant_code, redirect_uri }` | `{ line_user_id, display_name, picture_url }` | 97–123 |\n| `auth-send-otp` (Edge Function) | `{ phone, merchant_code }` | `{ session_id, expires_in, message }` | 126–156 |\n| `bff-auth-complete` (Edge Function) | `{ merchant_code, line_user_id?, tel?, otp_code?, session_id?, access_token?, selected_persona_id? }` | `{ next_step, user, access_token, refresh_token, is_new_user, missing, missing_data }` | 158–233 |\n| `bff-profile-lookup` (Edge Function) | Bearer end-user access token | `{ success, user_account }`; `user_account` is backed by `get_user_summary()` and includes `mongo_id` from `user_accounts.mongo_id` | — |\n| `superadmin_create_mcp_access_token` | `p_token_hash, p_token_prefix, p_label, p_scopes?, p_allowed_tools?, p_allowed_feature_slugs?, p_expires_at?, p_metadata?` | `{ id, token_prefix, scopes }` | Platform superadmin personal MCP key creation |\n| `superadmin_list_my_mcp_access_tokens` | none | `{ tokens }` | Lists current platform superadmin''s MCP key metadata |\n| `superadmin_revoke_my_mcp_access_token` | `p_token_id uuid` | `{ id }` | Revokes current platform superadmin''s MCP key |\n| `fn_validate_mcp_access_token` | `p_token_hash text` | `{ valid, owner_admin_user_id, scopes, allowed_tools, allowed_feature_slugs }` | Service-role validation for hosted MCP |\n**Key Business Rules (summary):**\n- All custom JWTs signed with Supabase Legacy JWT Secret (HS256)\n- End-user JWT includes custom claims: `merchant_id`, `user_id`, `phone`, `line_id`\n- `merchant_master.auth_methods` controls which auth methods are required per merchant\n- Phone normalization: `0966564526` → `+66966564526`\n- `next_step` drives the entire frontend routing after authentication\n- `bff-profile-lookup` returns the current member profile summary and exposes `user_account.mongo_id` for migrated users.\n- `selected_persona_id` lets signup return persona-scoped custom fields before `user_accounts.persona_id` is saved\n- Platform superadmin MCP keys are personal to `admin_users` with `admin_roles.role_code = ''platform_superadmin''`; raw keys are shown once and only SHA-256 hashes are stored in `system_mcp_access_tokens`.\n- MCP scopes start with `knowledge:read` and `knowledge:write`; hosted MCP validates bearer tokens through `fn_validate_mcp_access_token`.", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/authentication.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "703123aeefc4ee6d978f7d158df855419c5a9ee33a079a5444a5e10b5aec4a52", "truncated": false}, "is_active": true}, {"id": "bedfb2ed-be92-59bc-884d-cd277f7c6377", "feature_slug": "authentication-and-signup", "title": "6c. For Testers", "content": "**`next_step` state machine — test all 5 transitions:**\n\n| # | Precondition | Auth input | Expected `next_step` |\n|---|---|---|---|\n| 1 | No account exists, method=`[\"line\",\"tel\"]` | LINE only | `verify_tel` |\n| 2 | Existing account with tel, method changed to `[\"line\",\"tel\"]` | Phone OTP | `verify_line` |\n| 3 | Existing account, all methods linked, profile complete | Any valid auth | `complete` |\n| 4 | Existing account, `is_signup_form_complete=true`, new required fields | Any valid auth | `complete_profile_existing` |\n| 5 | Existing account, `is_signup_form_complete=false` | Any valid auth | `complete_profile_existing` |\n| 6 | No account, method=`[\"tel\"]` | Phone OTP | `complete_profile_new` |\n\n**`missing_data` content rules:**\n\n| Condition | Content |\n|---|---|\n| `complete_profile_new` (new user) | Full form: persona, all fields, PDPA |\n| `complete_profile_existing`, `is_signup_form_complete=false` | Full form (never submitted) |\n| `complete_profile_existing`, `is_signup_form_complete=true` | Missing required fields only |\n| `complete` | `null` |\n\n**Business rules as assertions:**\n\n- ASSERT: Phone `0966564526` is normalized to `+66966564526` before lookup/storage\n- ASSERT: OTP expires after 10 minutes; 4th attempt on same session fails\n- ASSERT: `bff-auth-complete` with mismatched LINE + phone (different accounts) returns error\n- ASSERT: Custom JWT contains `merchant_id`, `user_id`, `phone`, `line_id` claims\n- ASSERT: Access token expires after 24 hours; refresh token after 30 days\n- ASSERT: `form_step` skips steps with no content (e.g., no persona config → skip persona step)\n- ASSERT: `bff_save_user_profile` sets `is_signup_form_complete = true`\n- ASSERT: Profile form Next button is disabled until all required fields in current step are filled\n- ASSERT: PDPA mandatory consents must be accepted before Confirm\n- ASSERT: Empty `missing_data` from edge function shows error + Retry button (never auto-saves)\n\n**Bot testing shortcut:** `bff-auth-complete` accepts `bot_secret` field. When valid, OTP validation is skipped — phone is treated as verified. Requires `BOT_SECRET` env var on the Supabase project. Returns 403 if not configured or mismatched.\n\n**Error states to test:**\n\n| Input | Expected error |\n|---|---|\n| Missing `merchant_code` | `\"merchant_code is required\"` |\n| Invalid `merchant_code` | `\"Invalid merchant_code\"` |\n| Missing `otp_code` or `session_id` with `tel` | `\"Incomplete phone verification parameters\"` |\n| Wrong OTP / expired | `\"Invalid or expired OTP\"` |\n| LINE + phone belong to different accounts | `\"Credentials belong to different accounts\"` |", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/authentication-and-signup.md#L178 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "fa54bd0481b209dc63281b23fe7aa7e1dcdfe681ae0e141e92abbc733cfcbaeb", "truncated": false}, "is_active": true}, {"id": "dbd2652a-9323-5606-b274-ca978a3b15fc", "feature_slug": "authentication-and-signup", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current route / trigger | Data source |\n|---|---|---|\n| Auth Drawer (initial) | `useAuth().openAuthDrawer()` or manual trigger | `bff_get_auth_config` |\n| Auth Drawer (LINE redirect) | Homepage with `?code=&state=` params | `LineCallbackHandler` → `/api/auth/line/callback` |\n| Auth Drawer (profile gate) | Any non-home page, authenticated user | `AuthGate` → `checkProfileCompletion()` |\n| Profile Form (within drawer) | `next_step = complete_profile_*` | `bff-auth-complete` → `missing_data` |\n\n### 5a. Scenario 1 — New User, LINE + Phone Required\n\n1. Member opens app → Auth Drawer appears with LINE button + phone input (based on `auth_methods`)\n2. Taps LINE button → redirects to LINE OAuth\n3. LINE redirects back with `?code=` → `LineCallbackHandler` exchanges code via `auth-line` → gets `line_user_id`\n4. Calls `bff-auth-complete` with `line_user_id` → response: `next_step: \"verify_tel\"`\n5. Drawer shows phone input + \"Get OTP\" button\n6. Member enters phone → `auth-send-otp` sends SMS → `session_id` stored\n7. Member enters 6-digit OTP (auto-advances between input boxes)\n8. Calls `bff-auth-complete` with `line_user_id` + `tel` + `otp_code` + `session_id`\n9. New user created → response: `next_step: \"complete_profile_new\"`, `missing_data` = full form\n10. Drawer shows profile form: persona selection → default fields → custom fields → PDPA consents\n11. Member fills each step, Next button validates required fields before advancing\n12. On final step, Confirm → `bff_save_user_profile` saves data, sets `is_signup_form_complete = true`\n13. Drawer closes → homepage renders logged-in state\n\n### 5b. Scenario 2 — Existing User (Phone Only), Method Changed to LINE + Phone\n\n1. Member authenticates with phone OTP → `bff-auth-complete` detects missing LINE\n2. Response: `next_step: \"verify_line\"` with JWT issued\n3. Drawer shows LINE button with \"Please connect your LINE account\"\n4. Member taps LINE → OAuth redirect → returns with code\n5. `bff-auth-complete` called with `line_user_id` + `access_token` (for linking)\n6. LINE linked to existing account → response: `next_step: \"complete\"` (profile already complete)\n7. Drawer closes → homepage\n\n### 5c. Scenario 3 — Returning User, Complete Profile\n\n1. Member authenticates → `bff-auth-complete` finds existing user, all methods present, profile complete\n2. Response: `next_step: \"complete\"`, `missing_data: null`\n3. Drawer auto-closes → homepage\n\n### 5d. Scenario 4 — Existing User, New Required Fields Added\n\n1. Member authenticates → profile was previously complete, but merchant added new required fields\n2. Response: `next_step: \"complete_profile_existing\"`, `missing_data` = only the new missing fields\n3. Drawer shows abbreviated form with \"ยินดีต้อนรับกลับ!\" (Welcome back!) header\n4. Member fills missing fields → save → drawer closes\n\n### 5e. Scenario 5 — Existing User (LINE Only), Never Filled Form, Method Changed to LINE + Phone\n\n1. Member authenticates with LINE → `bff-auth-complete` detects missing phone\n2. Response: `next_step: \"verify_tel\"` with JWT issued\n3. Member verifies phone via OTP → `bff-auth-complete` links phone\n4. Profile not yet complete (`is_signup_form_complete = false`) → response: `next_step: \"complete_profile_existing\"`, `missing_data` = full form\n5. Member fills full form → save → homepage\n\n### 5f. Entry Points\n\n| Trigger | Location | Behavior |\n|---|---|---|\n| LINE redirect | `LineCallbackHandler` on homepage | Detects `?code=`, exchanges token, opens drawer if needed |\n| Profile gate | `AuthGate` on non-home pages | Authenticated user missing profile → opens drawer |\n| Manual | Any component via `useAuth().openAuthDrawer()` | Opens drawer fresh |", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/authentication-and-signup.md#L110 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "83f0367387a213efc4920c0b99bea6e0c14fe2810ef4c6c1d5f71ddd57fb8304", "truncated": false}, "is_active": true}, {"id": "99383939-13e5-55dc-af8d-01cbb0e10725", "feature_slug": "authentication-and-signup", "title": "6b. For Marketing", "content": "**Value proposition:** Authentication doubles as onboarding. Instead of a separate registration flow, members authenticate with LINE (one tap in Thailand''s dominant messaging app) and immediately enter a guided profile completion that captures persona, preferences, and consent — all in a single bottom-sheet interaction.\n\n**Use-case stories:**\n\n1. **Thai retail chain** — Uses `[\"line\", \"tel\"]` to capture both LINE identity (for LINE OA messaging) and phone (for SMS campaigns). Member taps LINE → verifies phone → selects persona → done. Two identity channels captured in under 60 seconds.\n\n2. **Event-based onboarding** — Members scan QR at an event, LINE authenticates them, and the profile form pre-fills event-specific address fields via `event_code`. Walk-in to registered member in one interaction.\n\n**Differentiators:**\n- **LINE-native** — one-tap authentication for Thailand''s largest messaging platform\n- **Progressive profiling** — form adapts to show only what''s missing, even months after initial signup\n- **Persona-aware fields** — different member types see different registration fields", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/authentication-and-signup.md#L178 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "authentication-and-signup", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "743c7f388fa92ee504490fade7808f927e4d64ed8039cdc53264e79e7309a5c9", "truncated": false}, "is_active": true}, {"id": "72ef43e4-3333-53fb-9176-d774c01e8592", "feature_slug": "bigcommerce-storefront-api", "title": "BigCommerce Storefront API Domain Reference", "content": "**Keywords:** bigcommerce, storefront, api_bigcommerce_*, mongoId, mongo_id, migrated user, member profile (storefront), member tier (storefront), storefront rewards, merchant config (storefront)\n**Source:** none (function-defined surface; this doc is the source of truth)\n| Function | Args | Auth | Returns |\n|---|---|---|---|\n| `api_bigcommerce_get_merchant_config(p_merchant_code text)` | merchant code | none (public) | merchant + tier + theme config keyed for storefront |\n| `api_bigcommerce_get_user_profile()` | — | `auth.uid()` + `get_current_merchant_id()` | profile + tier + wallet + `mongoId` |\n| `api_bigcommerce_get_user_rewards(p_limit int=100, p_page int=1)` | pagination | `auth.uid()` + `get_current_merchant_id()` | redeemed rewards filtered for the BigCommerce store channel |\n|---|---|---|\n| `_id` | `user_accounts.id` | UUID |\n| `mongoId` | `user_accounts.mongo_id` | Legacy Mongo ObjectId (text) **or `null`**. `null` = user signed up after migration. Use `mongoId != null` to detect a migrated user. |\n| `merchantId` | `user_accounts.merchant_id` | UUID |\n| `phoneNumber`, `email`, `fullName`, `lineUserId`, `avatar` | `user_accounts.tel/email/fullname/line_id/image` | empty string when null |\n| `memberCode` | derived: `to_char(created_at,''YYMMDDHH24MI'') || last 3 hex of id` | display code |\n| `userType` | hardcoded | always `''CLIENT''` |\n| `signupMethod` | derived | `''LINE''` if `line_id` set, else `''TEL''` |\n| `status` | hardcoded | always `''ACTIVE''` |\n| `memberTier` | `tier_master` + `tier_conditions` + `earn_factor` | nested object: `tierName, pointThreshold, color, icon, benefits, card_design, bahtSpent, points, discountInBaht, discountUsePoints, burnRate, burnRateEnabled, maxDiscountInBaht, status, isDefault, _id` |\n| `contact` | `user_accounts` + `user_wallet` | flat user record incl. `pointBalance`, `memberTierId/Name` |\n| `totalPoints` | `user_wallet.points_balance` | |\n| `totalCoupons` | hardcoded `0` | not yet wired |\n| `merchant` | `merchant_master` + all tiers | `_id, name, membershipTiers[], themeMode=''light''` |\n| `typeTier` | hardcoded | `''sale_earn''` |\n| `registerAt` | `user_accounts.created_at` | timestamptz |", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/bigcommerce-storefront-api.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "bigcommerce-storefront-api", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8324fc6f44c086ee097d3f3d684e0bf6cabf5c29a41e7d311ec33b1dcd1018ee", "truncated": false}, "is_active": true}, {"id": "4ec79136-049e-5731-81de-d4c52f519ba5", "feature_slug": "checkin", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page name | Current route | BFF / data source |\n|---|---|---|\n| Check-in List | _TBD — not yet in FE docs_ | `checkin` table direct query |\n| Check-in Settings (create) | _TBD_ | — |\n| Check-in Settings (edit) | _TBD_ | — |\n\n> Note: Admin frontend pages for check-in are not yet documented in the loyalty-admin repo. The journey below is inferred from the database schema. Routes will be added when the admin UI is implemented.\n\n### 4a. Create a New Check-in Campaign\n\n1. From **Check-in List**, click **\"Add check-in\"**\n2. **Check-in Settings** opens — empty form\n3. Fill campaign settings: name (required), description, frequency type (daily/weekly)\n4. Set timezone if different from default\n5. Optionally enable time window → set start/end times (supports overnight windows like 22:00–02:00)\n6. Optionally set campaign window (start/end dates) to limit when the campaign runs\n7. Set max streak days if the campaign should cap at a value other than 365\n8. Configure `require_condition_match` — if enabled, members who don''t match any condition are blocked from checking in\n9. Save the campaign\n\n### 4b. Configure Conditions (Reward Tiers)\n\n1. From campaign edit view, navigate to the conditions section\n2. Click **\"Add condition\"** to define a streak-day reward\n3. Set streak day range: start (required) and optional end. Example: start=1, end=6 for \"days 1 through 6\"\n4. Toggle `is_milestone` for special days (day 7, day 30) — controls frontend highlight treatment\n5. Set eligibility: select allowed tiers and user types (leave empty for unrestricted)\n6. Choose outcome entity: `points`, `tickets`, `reward`, or `earn_factor`\n7. For `points`: set outcome amount (e.g., 50 points). Entity ID not needed.\n8. For `tickets`: entity_id = ticket type UUID, outcome amount = 1 (always one ticket)\n9. For `reward`: entity_id = reward UUID. Triggers a free redemption via `redeem_reward_with_points`\n10. For `earn_factor`: entity_id = earn factor UUID. Assigns a 7-day multiplier\n11. Set priority (higher wins when multiple conditions match the same streak day and eligibility)\n12. Save condition — repeat for each streak bracket\n\n### 4c. Common Admin Mistakes\n\n- Setting `require_condition_match = true` with no conditions → every check-in attempt is rejected\n- Creating overlapping streak day ranges with no tier/type differentiation → highest-priority condition wins silently; admin may not realize which fires\n- Setting time window end before start without intending an overnight window → actually creates a day-crossing window (22:00 to 06:00), which may be unintended\n- Forgetting to set `active_status = true` on conditions → conditions are ignored\n- Using `reward` outcome entity with an invalid or inactive reward ID → redemption fails silently at check-in time\n- Setting campaign `window_end` in the past → campaign treated as not found", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/checkin.md#L70 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "checkin", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "454178746d5cc563af776f93ccb5a3ddfc8d89d01a8ba5b493917d041ead226b", "truncated": false}, "is_active": true}, {"id": "43eb50a9-761b-5f6d-ba8d-52d00f606958", "feature_slug": "checkin", "title": "7. Business Rules", "content": "**Rule:** One check-in per member per campaign per calendar day. Enforced by a unique constraint — even if called concurrently, only one succeeds.\n**Example:** Member taps check-in twice rapidly → first call succeeds, second returns \"Already checked in today.\"\n\n**Rule:** Streak continuity depends on frequency type. Daily: last check-in must be exactly yesterday. Weekly: last check-in must be within the past 7 days. Any larger gap resets the streak to 1.\n**Example:** Daily campaign, member checks in Mon–Fri, misses Sat → Sunday check-in starts streak at 1, not 6.\n\n**Rule:** Condition matching uses streak day range plus eligibility filters. The system finds conditions where `streak_day_start <= current_streak_day <= streak_day_end` AND the member''s tier and user type pass the filters. Highest priority wins; ties broken by highest outcome amount.\n**Example:** Day 7, two conditions: \"Day 7 milestone (priority 200, 50 pts)\" and \"Days 1–30 base (priority 100, 10 pts)\" → milestone wins.\n\n**Rule:** When `require_condition_match = true` and no condition matches, the entire check-in is rejected — no ledger entry, no streak update.\n**Example:** New campaign with no conditions yet + require_condition_match enabled → all check-in attempts fail.\n\n**Rule:** Time window evaluation uses the campaign''s configured timezone, not UTC or the member''s device timezone. Day-crossing windows (start > end) are handled correctly.\n**Example:** Campaign timezone = Asia/Bangkok, window = 22:00–02:00. Member in UTC checks in at 17:00 UTC (00:00 Bangkok) → succeeds.\n\n**Rule:** Empty eligibility arrays on conditions mean unrestricted. `allowed_tier_ids = NULL` matches all tiers.\n**Example:** Condition with no tier filter → Bronze through Diamond all receive the reward.\n\n**Rule:** Outcome type `reward` triggers a full reward redemption via `redeem_reward_with_points`. If the reward is out of stock or the member is ineligible for the reward, the redemption portion fails but the check-in and streak still advance.\n**Example:** Day 7 condition grants a free coffee reward. Coffee reward is out of stock → check-in records, streak updates, but no reward received.\n\n**Rule:** Outcome type `earn_factor` grants a temporary multiplier with a fixed 7-day expiry from check-in time. If the member already has the same factor, the expiry is extended (upsert).\n**Example:** Member earns 2x factor on day 14, already has it from day 7 → expiry resets to 7 days from now.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/checkin.md#L235 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "checkin", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "2073046f4a8113902593b0e07d334a08e59f71a9a883742a37407d1112b06589", "truncated": false}, "is_active": true}, {"id": "679c8c48-b89a-590b-a286-4e4e5b8d39b4", "feature_slug": "checkin", "title": "3. Configuration Reference", "content": "### Campaign Settings\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Name | Campaign display name | \"Daily Bonus\" | Required |\n| Description | Campaign description text | \"Check in daily for rewards\" | None |\n| Frequency type | Check-in cadence | `daily` | Required |\n| Timezone | Timezone for time window evaluation | `Asia/Bangkok` | `Asia/Bangkok` |\n| Enable time window | Restrict check-in to specific hours | `true` | `false` |\n| Window start time | Earliest allowed check-in time | `06:00` | — |\n| Window end time | Latest allowed check-in time | `22:00` | — |\n| Max streak days | Streak counter upper bound | 365 | 365 |\n| Campaign start (`window_start`) | Date campaign becomes active | 2025-01-01 | No restriction |\n| Campaign end (`window_end`) | Date campaign deactivates | 2025-12-31 | No restriction |\n| Require condition match | Block check-in if no condition matches | `true` | `false` |\n| Active status | Master on/off for the campaign | `true` | `true` |\n\n### Condition Settings\n\n| Setting | What it controls | Example | Default |\n|---|---|---|---|\n| Condition name | Label for admin reference | \"Day 7 Bonus\" | None |\n| Streak day start | First streak day this condition applies | 7 | Required |\n| Streak day end | Last streak day (null = open-ended) | 7 | None (unbounded) |\n| Is milestone | Flag for milestone UI treatment | `true` | `false` |\n| Allowed tier IDs | Which tiers earn this reward | [Gold ID, Platinum ID] | Empty = all tiers |\n| Allowed user types | Which user types qualify | [member, corporate] | Empty = all types |\n| Outcome entity | Reward type: `points`, `tickets`, `reward`, `earn_factor` | `points` | Required |\n| Entity ID | ID of the linked entity (ticket type, reward, earn factor) | UUID | null (not needed for points) |\n| Outcome amount | Quantity awarded | 50 | null |\n| Priority | Tiebreaker when multiple conditions match | 150 | 100 |\n| Active status | Enable/disable this condition | `true` | `true` |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/checkin.md#L35 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "checkin", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f82a6a6215eb6ea4062734af9738af8381bfce52b09dafde078cfb294df21ddd", "truncated": false}, "is_active": true}, {"id": "f43a5d59-f51f-5e9e-a02d-fbd6f2ea1e29", "feature_slug": "checkin", "title": "2. Key Concepts", "content": "**Check-in Campaign** — A merchant-configured attendance program with a name, frequency, and set of reward conditions. A merchant can run multiple campaigns simultaneously. Example: \"Daily Bonus\" (daily frequency) and \"Weekend Special\" (weekly frequency).\n\n**Frequency Type** — How often a member must check in to maintain their streak: `daily` (every calendar day) or `weekly` (within every 7-day rolling window).\n\n**Streak** — The count of consecutive check-ins without a gap. Resets to 1 when the member misses the required frequency window. Example: Member checks in 5 consecutive days → streak = 5. Misses day 6 → next check-in resets streak to 1.\n\n**Streak Day** — The current position in the streak, starting at 1. Used to match against condition rows. On each check-in, streak_day increments if continuity holds, or resets to 1 if broken.\n\n**Max Streak Days** — Upper bound on streak counting (default: 365). After reaching this cap, the streak value stops incrementing but check-ins continue recording.\n\n**Condition** — A row defining what a member earns at a specific streak range. Each condition specifies: streak day range (`streak_day_start` to `streak_day_end`), eligibility filters (tier, user type), outcome type, and outcome amount. Example: \"Days 1–6: earn 10 points; Day 7 (milestone): earn 50 points.\"\n\n**Milestone** — A condition flagged as `is_milestone = true`, typically representing a significant streak achievement (e.g., day 7, day 30). Used by the frontend to highlight special rewards in the streak calendar.\n\n**Outcome Entity** — What the member receives: `points` (currency credit), `tickets` (lottery entries), `reward` (free redemption of a specific reward), or `earn_factor` (temporary points multiplier). Each references an `entity_id` where applicable.\n\n**Time Window** — Optional daily hours during which check-in is allowed (e.g., 06:00–22:00). Evaluated in the campaign''s configured timezone. Supports day-crossing windows (e.g., 22:00–02:00).\n\n**Campaign Window** — Optional start/end dates (`window_start`, `window_end`) during which the campaign is active. Outside this range, the campaign is treated as not found.\n\n**Require Condition Match** — When `true`, a check-in without a matching condition is rejected entirely (no streak update, no ledger entry). When `false`, the check-in records and the streak advances even without a reward.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/checkin.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "checkin", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "0f6ba146fab6921b1d8552f08e24c183a42586f80ea7416e01cb686371d9993f", "truncated": false}, "is_active": true}, {"id": "780420b9-5e94-5d2a-98a2-17cb162cf2bb", "feature_slug": "checkin", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch**: \"Check-in rewards your members for showing up. They tap a button daily or weekly, build a streak, and earn escalating rewards — points on regular days, bigger bonuses on milestone days. It drives daily app opens without requiring a purchase.\"\n\n**Top 5 support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Member can''t check in\" | Check: is the campaign active? Is it within campaign window dates? Is the time window enabled and currently open? Has the member already checked in today? |\n| \"Member''s streak reset unexpectedly\" | Daily: member missed a calendar day. Weekly: gap exceeded 7 days. Streaks reset automatically — there is no manual override. |\n| \"Member checked in but got no reward\" | If `require_condition_match = false`, check-ins succeed without a reward when no condition matches. Check if conditions cover the member''s current streak day and tier. |\n| \"Member says reward amount is wrong\" | Multiple conditions may overlap. The system picks the highest-priority match. Check which condition fired by looking at the ledger''s `condition_id`. |\n| \"Check-in button shows wrong time window\" | Time is evaluated in the campaign''s configured timezone, not the member''s device timezone. Verify the campaign timezone setting. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/checkin.md#L165 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "checkin", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "48bd8af76c977d3f14a55ea5a6e31a465ce717e9915a5c09087b8fa8f6b6db51", "truncated": false}, "is_active": true}, {"id": "d758987f-cc9d-52dc-83c4-b17383d1637c", "feature_slug": "checkin", "title": "1. Overview", "content": "Check-in is a daily or weekly attendance mechanic that rewards members for returning consistently. A merchant creates a check-in campaign, defines what members earn at each streak milestone, and members tap a button in the app to record attendance. The system tracks consecutive check-ins as a streak and matches the current streak day to a condition row that determines the reward — points, tickets, a free reward, or an earn-rate multiplier.\n\nThe core engagement loop: member checks in → streak increments → condition determines today''s reward → member sees progress toward the next milestone. Missing a check-in resets the streak to day 1. This creates a lightweight, habit-forming touchpoint that drives daily app opens without requiring a purchase. Merchants can gate conditions by tier or user type, making check-in rewards progressively more valuable for higher-tier members.\n\nTwo frequency modes exist: **daily** (must check in on consecutive calendar days) and **weekly** (must check in within rolling 7-day windows). Both support optional time-of-day windows and campaign date ranges. Four outcome types cover the reward spectrum: direct points, lottery tickets, free reward redemptions, and temporary earn-factor multipliers.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/checkin.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "checkin", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "140d090d7c61c1e48659d9d69d32248a2726e8081335408a14beb76b61399a4b", "truncated": false}, "is_active": true}, {"id": "4756a344-f7d2-5bbd-8a51-58e27015b1c6", "feature_slug": "checkin", "title": "8. Related Features", "content": "| Feature | Connection to Check-in |\n|---|---|\n| Currency | Points and tickets are awarded through wallet transactions (`post_wallet_transaction`). See Currency guide. |\n| Tier | Conditions can be tier-gated via `allowed_tier_ids`. Higher tiers can earn better check-in rewards. See Tier guide. |\n| Rewards | The `reward` outcome type triggers a free redemption of a specific reward. See Rewards guide. |\n| Activity/Earning | The `earn_factor` outcome type assigns a temporary points multiplier from the earn system. See Activity guide. |\n| Mission | Missions may include check-in as a completion criterion (e.g., \"Check in 7 days\"). See Mission guide. |\n| Tag & Persona | Conditions currently filter by tier and user type; persona/tag filtering could extend this. See Tag & Persona guide. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/checkin.md#L261 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "checkin", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "65d6224894b7c261e51314b855caf906ec939a55fdcc3c2f4bb63adb398e0247", "truncated": false}, "is_active": true}, {"id": "8368cba0-ea52-5271-b48a-6b1f9e2e9896", "feature_slug": "checkin", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected behavior |\n|---|---|\n| `frequency_type = daily`, check in 2 consecutive days | `streak_day` = 2 on second check-in |\n| `frequency_type = daily`, skip a day, check in | `streak_day` resets to 1 |\n| `frequency_type = weekly`, check in within 7 days | Streak continues (increments) |\n| `frequency_type = weekly`, gap > 7 days | Streak resets to 1 |\n| `enable_time_window = true`, outside window | \"Outside check-in window\" error with start/end times |\n| Day-crossing window (22:00–02:00), check in at 23:00 | Check-in succeeds (within window) |\n| Day-crossing window (22:00–02:00), check in at 10:00 | \"Outside check-in window\" error |\n| Same member, same campaign, same day, second attempt | \"Already checked in today\" error |\n| `require_condition_match = true`, no matching condition | Check-in rejected entirely |\n| `require_condition_match = false`, no matching condition | Check-in succeeds, streak advances, no reward |\n| Two conditions match same streak day, different priorities | Higher priority wins |\n| Campaign `active_status = false` | \"Campaign not found or inactive\" error |\n| Campaign outside `window_start/window_end` dates | \"Campaign not found or inactive\" error |\n| Streak reaches `max_streak_days` | Streak stops incrementing but check-ins still record |\n| Outcome `points`: amount = 50 | 50 points credited to wallet, transaction description includes campaign name |\n| Outcome `tickets`: entity_id = ticket_type_id | 1 ticket added to wallet for that ticket type |\n| Outcome `reward`: entity_id = reward_id | Free redemption triggered via `redeem_reward_with_points` |\n| Outcome `earn_factor`: entity_id = factor_id | Earn factor assigned with 7-day expiry |\n\n**Business rules as assertions:**\n\n- ASSERT: One check-in per user per campaign per calendar day (unique constraint on `user_id + merchant_id + checkin_id + checkin_date`)\n- ASSERT: Streak resets to 1 when daily gap > 1 day or weekly gap > 7 days\n- ASSERT: `longest_streak` = MAX of all `current_streak` values ever recorded\n- ASSERT: `total_checkins` increments by 1 on every successful check-in\n- ASSERT: Condition matching evaluates `streak_day_start <= streak_day <= streak_day_end` AND tier AND user_type, ordered by priority DESC then outcome_amount DESC\n- ASSERT: `next_deadline` for daily = end of tomorrow; for weekly = now + 7 days\n- ASSERT: Points outcome calls `post_wallet_transaction` with source_type = `campaign`\n- ASSERT: Earn factor outcome sets `window_end` = now + 7 days\n\n**Duplicate prevention:** Enforced at both the application level (check before insert) and database level (unique index on `checkin_ledger(user_id, merchant_id, checkin_id, checkin_date)`).", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/checkin.md#L165 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "checkin", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ebeff608c46a1d7a072ff5d300fb3c49b5ad6f21dce6bdde6981896ef11c95d1", "truncated": false}, "is_active": true}, {"id": "7cbd6b16-75a5-5383-bff0-8ef5a880568b", "feature_slug": "checkin", "title": "5. Member Experience", "content": "**Repo:** `Rocket-CRM/loyalty-user`\n\n**Route map:**\n\n| Page / Component | Current route | Data source |\n|---|---|---|\n| Check-in page / widget | _TBD — not yet in FE docs_ | `get_user_checkin_status()` |\n| Check-in result | _TBD_ | `process_checkin()` response |\n\n> Note: Member-facing screens for check-in are not yet documented in the loyalty-user repo. The journey below is inferred from the database functions.\n\n### 5a. View Check-in Status\n\n1. Member opens the check-in page or widget\n2. App calls `get_user_checkin_status(user_id, merchant_id, checkin_id)`\n3. Response shows: `can_checkin` (boolean), `checked_today`, `in_window`, `current_streak`, `longest_streak`, `total_checkins`, `last_checkin` date, `next_deadline`, and time window if enabled\n4. If `checked_today = true`: check-in button is disabled, showing \"Already checked in\"\n5. If `in_window = false`: check-in button disabled, showing \"Outside check-in hours\" with window start/end times\n6. If `can_checkin = true`: check-in button is active\n\n### 5b. Perform Check-in\n\n1. Member taps the check-in button\n2. App calls `process_checkin(user_id, merchant_id, checkin_id)`\n3. On success: response includes `streak_day`, `total_checkins`, `longest_streak`, reward details (type, amount, entity_id, transaction_id), and `next_checkin` date\n4. Member sees streak progress update and reward animation/confirmation\n5. If a condition matched: reward is displayed (e.g., \"+50 points\", \"Ticket earned\", \"Free reward claimed\")\n6. If no condition matched and `require_condition_match = false`: check-in succeeds with no reward\n\n### 5c. Error States\n\n1. \"Check-in campaign not found or inactive\" — campaign is off, outside window dates, or deleted\n2. \"Outside check-in window\" — current time is outside the allowed hours (includes start/end times in response)\n3. \"Already checked in today\" — duplicate prevention (one per campaign per calendar day)\n4. \"No rewards available for your profile\" — `require_condition_match = true` and no condition matches the member''s streak day, tier, or user type\n\n### 5d. Streak Behavior\n\n1. **Daily frequency**: streak continues if last check-in was exactly yesterday. Any gap resets to day 1.\n2. **Weekly frequency**: streak continues if last check-in was within the past 7 days. Gaps longer than 7 days reset to day 1.\n3. Streak progress is visible via `current_streak` (active run), `longest_streak` (personal best), and `total_checkins` (lifetime count).\n4. `next_deadline` shows when the member must check in by to maintain the streak.", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/checkin.md#L120 5. Member Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "checkin", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ac0a5e3da612e68011c667bd13e938a432c6f509c4c68d6b37239ed28db34829", "truncated": false}, "is_active": true}, {"id": "a5504925-dc2a-5046-a7e7-318d7d7f255b", "feature_slug": "checkin", "title": "6b. For Marketing", "content": "**Value proposition**: Check-in is the simplest daily engagement hook in the platform. Members build a habit of opening the app each day, and merchants reward consistency with escalating benefits — making each consecutive day more valuable than the last.\n\n**Use-case stories:**\n\n1. **Coffee chain** — \"Daily Check-in\" campaign: days 1–6 earn 5 points, day 7 milestone earns 50 points + a free coffee reward. Average member opens the app 5.2 days/week to maintain their streak.\n\n2. **Department store** — Tier-differentiated check-in: Gold members earn 10 points/day, Platinum members earn 20 points/day on the same campaign. Day-30 milestone grants a lottery ticket for a seasonal prize draw.\n\n3. **Fitness brand** — Weekly check-in for casual engagement: one check-in per week maintains the streak. Day-4 milestone (4 weeks) grants a 2x earn factor for 7 days, incentivizing purchases during the multiplier window.\n\n4. **Limited-time event** — Campaign with `window_start/end` set to a festival week. Time window 10:00–14:00 for lunch-hour engagement. Milestones at day 3 and day 7 drive repeat visits during the event period.\n\n**Metrics merchants care about**: Daily active users (check-in as proxy for app opens), streak distribution (how many members reach day 7, 14, 30), check-in-to-purchase conversion rate, streak recovery rate (how often broken streaks restart vs. members dropping off).", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/checkin.md#L165 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "checkin", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "13068988f5cd869f269d8c8ef945f16df23362dd7cb2e8261fb34dc5b14cc2ab", "truncated": false}, "is_active": true}, {"id": "0664a68a-ee4a-5d89-97be-3510394cdf46", "feature_slug": "cs-actions-feature-spec", "title": "5. ACTIONS", "content": "### 5.1 Integrated Platform Actions (via API)\n\n**Marketplace actions (Shopee, Lazada, TikTok Shop):**\n- View order details\n- Cancel unfulfilled order\n- Accept buyer cancellation request\n- Accept return/refund request\n- Propose partial refund\n- Recall cancellation/refund (Duoke has this)\n- Create voucher/discount code (fixed amount, percentage, min order, product-specific)\n- Send product card in chat\n- Send order card in chat\n- Send voucher card in chat\n- Update shipping status / mark as shipped\n- View and reply to product reviews\n\n**Shopify actions:**\n- All of the above plus: edit order items, update shipping address, reship, manage subscriptions (via Recharge/Loop)\n\n**LINE OA actions:**\n- Send flex message, rich message, push notification\n- Update rich menu per customer segment\n- Issue loyalty points (via CRM bridge)\n- Send reward notification\n\n**CRM/Loyalty actions (via internal API bridge — CRM is master for loyalty domain):**\n\nTags, personas, and loyalty vouchers/points are owned by the CRM. CS AI reads/writes via bridge API. This ensures shared constraints/budgets and one audit trail across AMP and CS AI.\n\nBridge endpoints:\n- READ: `GET /loyalty/{user_id}/context` → points, tier, rewards\n- READ: `GET /assets/tags` → available tag definitions\n- READ: `GET /assets/personas` → available persona definitions\n- WRITE: `POST /loyalty/{user_id}/points` → issue bonus points\n- WRITE: `POST /loyalty/{user_id}/voucher` → create loyalty voucher from template\n- WRITE: `POST /users/{user_id}/tags` → assign tag\n- WRITE: `POST /users/{user_id}/tags/remove` → remove tag\n- WRITE: `POST /users/{user_id}/persona` → update persona\n\nMaps to existing CRM functions (`post_wallet_transaction`, `fn_execute_amp_action`) — same execution path as AMP.\n\n**Important distinction — loyalty vouchers vs platform vouchers:**\n\n| Voucher Type | Master | Created Via | Example |\n|---|---|---|---|\n| **Loyalty voucher** | CRM | Bridge API → CRM function | \"฿200 store credit in loyalty app\", \"100 bonus points\" |\n| **Shopee shop voucher** | Shopee platform | `@Create Shopee Voucher` → Shopee `v2.voucher.add_voucher` API directly | \"10% off Shopee shop voucher\" |\n| **Lazada voucher** | Lazada platform | `@Create Lazada Voucher` → Lazada `/promotion/voucher/create` API directly | \"฿50 Lazada discount code\" |\n| **TikTok discount** | TikTok platform | `@Create TikTok Voucher` → TikTok API directly | Platform promotion |\n\nPlatform vouchers do NOT go through CRM. They''re created directly on the marketplace platform via its API. CRM doesn''t need to know about Shopee vouchers — they exist in a different system.\n\nThe AI picks the right type based on context: customer on Shopee → platform voucher. Loyalty member on LINE → loyalty voucher. Tags and personas assigned by CS AI are immediately visible in CRM analytics and vice versa.\n\n### 5.2 Custom API Action Builder\n\nFor any system with an API that doesn''t have a pre-built connector:\n- Visual builder: configure method (GET/POST/PUT/DELETE), URL, headers, body\n- Variable injection: use customer data, conversation data, AI-collected data in the request\n- AI information collection: define what the AI needs to ask the customer before calling the API\n- Response mapping: AI interprets the API response and crafts a natural reply\n- Conditional paths: different follow-up based on API response (success, error, partial)\n- Error handling: retry logic, fallback message, escalate on failure\n- Test mode: try the action with sample data before going live\n- Rate limiting: configure max calls per minute\n- Audit log: every API call logged with request, response, timestamp, conversation ID\n\n### 5.3 Computer Use Agent (Browser Automation)\n\nFor legacy systems without APIs (insurance claim portals, hospital booking systems, government portals, old CRM):\n- AI agent controls a browser to navigate UIs like a human agent\n- Powered by: Anthropic Claude computer use / Amazon Nova Act / similar\n- Isolated sandboxed browser session per action\n- Credential vault: secure storage, credentials never exposed to the LLM\n- URL whitelist: agent can only access pre-approved systems\n- Action recording: every click, keystroke, page load captured as screenshots + log\n- Human-in-the-loop option: AI proposes the action, human approves, AI executes\n- Fallback: if browser automation fails, escalate to human with context\n- Use cases: submit insurance claim in legacy portal, book appointment in hospital system, update customer record in old CRM\n\n### 5.4 Action Governance\n\n- **Approval workflows**: certain actions require human approval (refund above threshold, account closure, policy cancellation)\n- **Confirmation with customer**: AI asks \"Shall I proceed?\" before irreversible actions\n- **Undo / rollback**: where possible, provide undo within a time window\n- **Audit trail**: every action logged (who initiated, what was done, when, outcome)\n- **Action analytics**: track which actions are executed most, success/failure rates\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/CS_Actions.md#L5 5. ACTIONS", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "overview", "feature_slug": "cs-actions-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "9d8c70581c19dede8f864cfb48de083efb8b01d90bdfed7e47171fee69545f01", "truncated": false}, "is_active": true}, {"id": "0a43a437-3e40-5e5c-a3cd-7cbad97a6ade", "feature_slug": "cs-actions-feature-spec", "title": "CS Actions (Feature Spec) Domain Reference", "content": "**Keywords:** marketplace_action, cancel_order, process_refund, create_voucher, shopify, loyalty_bridge, custom_api_builder, computer_use, browser_automation, action_governance, approval_workflow\n**Source:** `CS_Actions.md`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-actions-feature-spec.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-actions-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c780d410812be1f4c6486c74775ec0b4db3d400c8bb075fac5ec54849cab55a6", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
